type WorkspaceTab = "words" | "review";

interface DictionaryStatus {
  available: boolean;
  name: string | null;
  wordCount: number;
  reason?: string;
}

const masteryLabels = {
  new: "新词",
  learning: "学习中",
  review: "复习中",
  mastered: "已掌握",
} as const;

function dueText(word: VocabularyWord) {
  const due = new Date(word.nextReviewAt).getTime();
  const now = Date.now();
  if (due <= now) return "今天复习";
  const days = Math.max(1, Math.ceil((due - now) / 86_400_000));
  return `${days} 天后`;
}

function speakingSupported() {
  return typeof window !== "undefined" && "speechSynthesis" in window;
}

function speak(text: string) {
  if (!speakingSupported()) return false;
  window.speechSynthesis.cancel();
  const utterance = new SpeechSynthesisUtterance(text);
  utterance.lang = "en-US";
  utterance.rate = 0.86;
  window.speechSynthesis.speak(utterance);
  return true;
}

function spellingDistance(left: string, right: string) {
  const rows = Array.from({ length: left.length + 1 }, (_, index) => [
    index,
    ...Array(right.length).fill(0),
  ]);
  for (let column = 0; column <= right.length; column += 1) {
    rows[0]![column] = column;
  }
  for (let row = 1; row <= left.length; row += 1) {
    for (let column = 1; column <= right.length; column += 1) {
      const cost = left[row - 1] === right[column - 1] ? 0 : 1;
      rows[row]![column] = Math.min(
        (rows[row - 1]![column] ?? 0) + 1,
        (rows[row]![column - 1] ?? 0) + 1,
        (rows[row - 1]![column - 1] ?? 0) + cost,
      );
    }
  }
  return rows[left.length]?.[right.length] ?? Math.max(left.length, right.length);
}

function coverStyle(theme: VocabularyCoverTheme, accent: string): CSSProperties {
  const selected =
    COVER_THEMES.find((item) => item.id === theme) ?? COVER_THEMES[0]!;
  return {
    "--wordbook-cover": selected.accent || accent,
    "--wordbook-cover-secondary": selected.secondary,
  } as CSSProperties;
}

export function VocabularyPage() {
  const navigate = useNavigate();
  const corpus = useInkFlow((state) => state.corpus);
  const {
    initialized,
    book,
    words,
    reviewMode,
    reviewDirection,
    session,
    hydrate,
    updateBook,
    addInsight,
    addManyInsights,
    removeWord,
    setReviewMode,
    setReviewDirection,
    startReview,
    gradeCurrentWord,
    closeReview,
  } = useVocabulary();
  const [activeTab, setActiveTab] = useState<WorkspaceTab>("words");
  const [query, setQuery] = useState("");
  const [selectedWordId, setSelectedWordId] = useState<string | null>(null);
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [dictionaryQuery, setDictionaryQuery] = useState("");
  const [dictionaryResult, setDictionaryResult] =
    useState<LanguageInsight | null>(null);
  const [dictionaryLoading, setDictionaryLoading] = useState(false);
  const [dictionaryStatus, setDictionaryStatus] =
    useState<DictionaryStatus | null>(null);
  const [spellingInput, setSpellingInput] = useState("");
  const [spellingChecked, setSpellingChecked] = useState(false);
  const [flipped, setFlipped] = useState(false);
  const [notice, setNotice] = useState<string | null>(null);
  const [bulkWords, setBulkWords] = useState("");
  const recordedReviewRef = useRef("");

  useEffect(() => {
    void hydrate();
  }, [hydrate]);

  useEffect(() => {
    void api
      .dictionaryStatus()
      .then(setDictionaryStatus)
      .catch(() =>
        setDictionaryStatus({
          available: false,
          name: null,
          wordCount: 0,
          reason: "API offline",
        }),
      );
  }, []);

  useEffect(() => {
    if (!notice) return;
    const timer = window.setTimeout(() => setNotice(null), 2600);
    return () => window.clearTimeout(timer);
  }, [notice]);

  useEffect(() => {
    if (!selectedWordId && words[0]) setSelectedWordId(words[0].id);
  }, [selectedWordId, words]);

  const filteredWords = useMemo(() => {
    const normalized = query.trim().toLowerCase();
    if (!normalized) return words;
    return words.filter((word) =>
      [
        word.term,
        word.definitionEn,
        word.meaningsZh.join(" "),
        word.sourceLabel,
        word.collocations.join(" "),
      ]
        .join(" ")
        .toLowerCase()
        .includes(normalized),
    );
  }, [query, words]);

  const selectedWord = useMemo(
    () => words.find((word) => word.id === selectedWordId) ?? words[0],
    [selectedWordId, words],
  );
  const dueWords = useMemo(() => dueVocabularyWords(words), [words]);
  const counts = useMemo(() => vocabularyMasteryCounts(words), [words]);
  const currentSessionWord = useMemo(() => {
    if (!session || session.completed) return undefined;
    const id = session.wordIds[session.index];
    return words.find((word) => word.id === id);
  }, [session, words]);

  useEffect(() => {
    setFlipped(false);
    setSpellingInput("");
    setSpellingChecked(false);
  }, [currentSessionWord?.id, session?.round]);

  useEffect(() => {
    if (!session?.completed) return;
    const key = `${session.roundWordIds.join(",")}:${Object.values(
      session.ratings,
    )
      .flat()
      .join(",")}`;
    if (recordedReviewRef.current === key) return;
    recordedReviewRef.current = key;
    const passed = session.roundWordIds.filter(
      (wordId) =>
        (session.ratings[wordId]?.filter(
          (rating) => rating === "good" || rating === "easy",
        ).length ?? 0) >= 2,
    ).length;
    recordStudyEvent({
      kind: "word-review",
      at: Date.now(),
      reviewed: session.roundWordIds.length,
      passed,
      failed: Math.max(0, session.roundWordIds.length - passed),
    });
  }, [session]);

  const notify = (message: string) => setNotice(message);

  const handleDictionarySearch = async (
    event?: FormEvent<HTMLFormElement>,
  ) => {
    event?.preventDefault();
    const term = dictionaryQuery.trim();
    if (!term) return;
    setDictionaryLoading(true);
    try {
      const response = await api.dictionary(term);
      setDictionaryResult(response.insight);
    } catch {
      setDictionaryResult(fallbackInsight(term));
    } finally {
      setDictionaryLoading(false);
    }
  };

  const handleDictionaryAdd = () => {
    if (!dictionaryResult) return;
    addInsight(dictionaryResult, "Oxford dictionary");
    setSelectedWordId(
      words.find(
        (word) =>
          word.term.toLowerCase() === dictionaryResult.term.toLowerCase(),
      )?.id ?? null,
    );
    notify(`已加入单词本：${dictionaryResult.term}`);
  };

  const handleBulkWordImport = () => {
    const terms = Array.from(
      new Set(
        bulkWords
          .split(/\r?\n/)
          .map((line) => line.trim())
          .filter(Boolean),
      ),
    );
    if (terms.length === 0) {
      notify("请先粘贴需要加入的单词，每行一个。");
      return;
    }
    const added = addManyInsights(
      terms.map((term) => fallbackInsight(term)),
      "自定义单词本",
      "逐行粘贴导入",
    );
    notify(
      added > 0
        ? `已加入 ${added} 个自定义单词`
        : "这些单词已经在单词本里了",
    );
    setBulkWords("");
  };

  const handleSpellingSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    checkSpelling();
  };

  const checkSpelling = () => {
    if (!currentSessionWord || !spellingInput.trim()) return;
    setSpellingChecked(true);
  };

  const handleSpellingNext = () => {
    if (!currentSessionWord) return;
    const answer = spellingInput.trim().toLowerCase();
    const expected = currentSessionWord.term.trim().toLowerCase();
    const distance = spellingDistance(answer, expected);
    gradeCurrentWord(
      distance === 0 ? "good" : distance <= 2 ? "hard" : "again",
    );
  };

  const spellingExact =
    spellingChecked &&
    currentSessionWord &&
    spellingInput.trim().toLowerCase() ===
      currentSessionWord.term.trim().toLowerCase();
  const spellingClose =
    spellingChecked &&
    currentSessionWord &&
    !spellingExact &&
    spellingDistance(
      spellingInput.trim().toLowerCase(),
      currentSessionWord.term.trim().toLowerCase(),
    ) <= 2;

  const coverTheme =
    COVER_THEMES.find((theme) => theme.id === book.theme) ?? COVER_THEMES[0]!;
  const masteryPercent =
    words.length > 0
      ? Math.round(((counts.review + counts.mastered) / words.length) * 100)
      : 0;

  if (!initialized) {
    return (
      <div className="wordbook-loading">
        <LoaderCircle size={30} />
        <span>Opening your wordbook</span>
      </div>
    );
  }

  return (
    <section className="wordbook-page" data-motion="enter">
      <LiquidGlass
        as="header"
        className="wordbook-topbar"
        intensity="strong"
      >
        <button
          type="button"
          className="wordbook-icon-button"
          onClick={() => navigate("/study")}
          aria-label="返回书房"
          title="返回书房"
        >
          <ArrowLeft size={18} />
        </button>
        <div className="wordbook-topbar__title">
          <img src="/leafia-mark.svg" alt="" />
          <span>
            <strong>{book.name}</strong>
            <small>Ebbinghaus Wordbook</small>
          </span>
        </div>
        <div className="wordbook-topbar__progress">
          <span>
            <Flame size={14} />
            今日待复习 <strong>{dueWords.length}</strong>
          </span>
          <i />
          <span>
            已掌握 <strong>{counts.mastered}</strong>
          </span>
        </div>
        <div className="wordbook-topbar__actions">
          <button
            type="button"
            className="wordbook-icon-button"
            onClick={() => setSettingsOpen(true)}
            aria-label="自定义封面"
            title="自定义封面"
          >
            <Settings2 size={17} />
          </button>
          <button
            type="button"
            className="wordbook-primary-button"
            onClick={() => {
              startReview();
            }}
          >
            <BookCheck size={16} />
            开始复习
          </button>
        </div>
      </LiquidGlass>

      <div className="wordbook-layout">
        <aside className="wordbook-rail">
          <div
            className="wordbook-cover"
            style={coverStyle(book.theme, book.accent)}
          >
            <span className="wordbook-cover__spine" />
            <span className="wordbook-cover__rule" />
            <small>LEAFIA · OXFORD EDITION</small>
            <strong>{book.name}</strong>
            <em>{book.subtitle}</em>
            <i>WORDBOOK</i>
          </div>

          <div className="wordbook-rail__stats">
            <span>
              <strong>{words.length}</strong>
              <small>词条</small>
            </span>
            <span>
              <strong>{counts.review + counts.mastered}</strong>
              <small>进入复习</small>
            </span>
            <span>
              <strong>{dueWords.length}</strong>
              <small>今日到期</small>
            </span>
          </div>

          <nav className="wordbook-nav" aria-label="单词书视图">
            <RubberSegment
              items={[
                { value: "words", label: "我的单词" },
                { value: "review", label: "复习计划" },
              ]}
              value={activeTab}
              onChange={(value: string) =>
                setActiveTab(value as WorkspaceTab)
              }
              size="md"
              radius={10}
              inset={3}
              trackColor="rgba(255,255,255,.42)"
              thumbColor="#17181a"
              textColor="#5d625f"
              activeTextColor="#ffffff"
              draggable
              aria-label="单词书视图"
            />
          </nav>

          <div className="wordbook-mastery-gauge">
            <SloshGauge
              value={masteryPercent}
              showValue
              liquidColor="#6a5dff"
              glassColor="rgba(255,255,255,.72)"
              width={72}
              height={132}
              radius={18}
              ticks={4}
              unit="%"
              ariaLabel="单词掌握进度"
            />
            <span>掌握进度</span>
          </div>

          <div className="wordbook-rail__note">
            <Sparkles size={15} />
            <p>每个词至少完成两轮复习，才会进入更长的记忆间隔。</p>
          </div>
        </aside>

        <main className="wordbook-main">
          {activeTab === "words" && (
            <>
              <header className="wordbook-section-head">
                <div>
                  <span className="wordbook-eyebrow">My vocabulary</span>
                  <h1>单词本</h1>
                  <p>按掌握阶段整理，点击词条查看释义与来源。</p>
                </div>
                <label className="wordbook-search">
                  <Search size={16} />
                  <input
                    type="search"
                    value={query}
                    onChange={(event) => setQuery(event.target.value)}
                    placeholder="搜索单词、释义或来源"
                  />
                </label>
              </header>

              <div className="wordbook-mastery-strip">
                {Object.entries(masteryLabels).map(([key, label]) => (
                  <div key={key} className={`is-${key}`}>
                    <i />
                    <span>{label}</span>
                    <strong>{counts[key as keyof typeof counts]}</strong>
                  </div>
                ))}
              </div>

              <section className="wordbook-line-import">
                <header>
                  <span className="wordbook-eyebrow">Custom word list</span>
                  <strong>逐行粘贴单词</strong>
                  <small>一行一个单词或短语，自动创建你自己的单词书。</small>
                </header>
                <textarea
                  value={bulkWords}
                  onChange={(event) => setBulkWords(event.target.value)}
                  placeholder={"solitude\ncompetitive edge\nin the wake of"}
                  spellCheck={false}
                />
                <button
                  type="button"
                  className="wordbook-primary-button"
                  onClick={handleBulkWordImport}
                  disabled={!bulkWords.trim()}
                >
                  创建自定义单词本
                </button>
              </section>

              <div className="wordbook-content-grid">
                <section className="wordbook-word-grid">
                  {filteredWords.map((word) => (
                    <div
                      key={word.id}
                      className={cn(
                        "wordbook-word-card",
                        selectedWord?.id === word.id && "is-selected",
                      )}
                      onClick={() => setSelectedWordId(word.id)}
                    >
                      <FlipCard
                        width={280}
                        height={220}
                        radius={12}
                        background="#fffdf9"
                        color="#1f2529"
                        shadow={false}
                        tilt={false}
                        draggable={false}
                        front={
                          <div className="wordbook-flip-word">
                            <header>
                              <span className={`is-${word.mastery}`}>
                                {masteryLabels[word.mastery]}
                              </span>
                              <small>{word.cefr ?? "B1-B2"}</small>
                            </header>
                            <strong>{word.term}</strong>
                            <p>{word.meaningsZh.join("；")}</p>
                            <div
                              className="wordbook-stage-dots"
                              aria-hidden="true"
                            >
                              {REVIEW_INTERVALS_DAYS.map((_, index) => (
                                <i
                                  key={index}
                                  className={cn(
                                    index <= word.reviewStage && "is-on",
                                  )}
                                />
                              ))}
                            </div>
                          </div>
                        }
                        back={
                          <div className="wordbook-flip-word is-back">
                            <small>{word.term}</small>
                            <strong>{word.definitionEn}</strong>
                            {word.examples[0] && (
                              <blockquote>{word.examples[0].text}</blockquote>
                            )}
                            <footer>
                              <span>{word.sourceLabel}</span>
                              <span>{dueText(word)}</span>
                            </footer>
                          </div>
                        }
                      />
                    </div>
                  ))}
                  {filteredWords.length === 0 && (
                    <div className="wordbook-empty">
                      <Search size={24} />
                      <strong>没有匹配的词条</strong>
                      <p>换个关键词，或从右侧词典添加新词。</p>
                    </div>
                  )}
                </section>

                <aside className="wordbook-detail">
                  {selectedWord ? (
                    <>
                      <header>
                        <div>
                          <span className="wordbook-eyebrow">
                            {selectedWord.partOfSpeech ?? "language entry"}
                          </span>
                          <h2>{selectedWord.term}</h2>
                          <p>
                            {selectedWord.pronunciation ?? selectedWord.lemma}
                          </p>
                        </div>
                        <button
                          type="button"
                          className="wordbook-icon-button"
                          onClick={() =>
                            speak(selectedWord.term) ||
                            notify("当前浏览器不支持语音朗读")
                          }
                          aria-label="朗读"
                        >
                          <Volume2 size={16} />
                        </button>
                      </header>
                      <div className="wordbook-detail__meaning">
                        {selectedWord.meaningsZh.join("；")}
                      </div>
                      <p className="wordbook-detail__definition">
                        {selectedWord.definitionEn}
                      </p>
                      <section>
                        <span>常见搭配</span>
                        <div className="wordbook-chips">
                          {selectedWord.collocations.map((collocation) => (
                            <button
                              type="button"
                              key={collocation}
                              onClick={() => {
                                setDictionaryQuery(collocation);
                                void handleDictionarySearch();
                              }}
                            >
                              {collocation}
                            </button>
                          ))}
                        </div>
                      </section>
                      {selectedWord.examples[0] && (
                        <section className="wordbook-example">
                          <span>例句</span>
                          <p>{selectedWord.examples[0].text}</p>
                          {selectedWord.examples[0].translationZh && (
                            <small>
                              {selectedWord.examples[0].translationZh}
                            </small>
                          )}
                        </section>
                      )}
                      <section className="wordbook-schedule-card">
                        <div>
                          <Clock3 size={15} />
                          <span>{stageLabel(selectedWord)}</span>
                        </div>
                        <strong>{dueText(selectedWord)}</strong>
                        <small>
                          已复习 {selectedWord.reviewCount} 次 · 连续记住{" "}
                          {selectedWord.correctStreak} 次
                        </small>
                      </section>
                      <footer>
                        <button
                          type="button"
                          className="wordbook-secondary-button"
                          onClick={() =>
                            speak(selectedWord.examples[0]?.text ?? selectedWord.term) ||
                            notify("当前浏览器不支持语音朗读")
                          }
                        >
                          <Volume2 size={15} />
                          朗读例句
                        </button>
                        <button
                          type="button"
                          className="wordbook-danger-button"
                          onClick={() => {
                            removeWord(selectedWord.id);
                            setSelectedWordId(null);
                          }}
                        >
                          <Trash2 size={15} />
                          移除
                        </button>
                      </footer>
                    </>
                  ) : (
                    <div className="wordbook-empty">
                      <BookOpen size={24} />
                      <strong>选择一条词汇</strong>
                      <p>释义、搭配和复习进度会显示在这里。</p>
                    </div>
                  )}
                </aside>
              </div>
            </>
          )}

          {activeTab === "review" && (
            <section className="wordbook-review-view">
              <header className="wordbook-section-head">
                <div>
                  <span className="wordbook-eyebrow">Memory schedule</span>
                  <h1>艾宾浩斯复习</h1>
                  <p>翻卡与拼写交替进行，每个词至少完成两轮回忆。</p>
                </div>
                <button
                  type="button"
                  className="wordbook-primary-button"
                  onClick={startReview}
                  disabled={words.length === 0}
                >
                  <BookCheck size={16} />
                  开始今日复习
                </button>
              </header>

              <section className="wordbook-review-hero">
                <div className="wordbook-review-hero__copy">
                  <span className="wordbook-eyebrow">Today</span>
                  <h2>{dueWords.length} 个词等待复习</h2>
                  <p>
                    先凭记忆回答，再根据难度安排下一次间隔。新词至少复习两次。
                  </p>
                  <div className="wordbook-review-modes">
                    <button
                      type="button"
                      className={cn(reviewMode === "flashcard" && "is-active")}
                      onClick={() => setReviewMode("flashcard")}
                    >
                      <RotateCcw size={16} />
                      翻卡背诵
                    </button>
                    <button
                      type="button"
                      className={cn(reviewMode === "spelling" && "is-active")}
                      onClick={() => setReviewMode("spelling")}
                    >
                      <Keyboard size={16} />
                      拼写检查
                    </button>
                  </div>
                  <div className="wordbook-direction-control">
                    <span>卡片方向</span>
                    <div>
                      {[
                        ["english-chinese", "英 → 中"],
                        ["chinese-english", "中 → 英"],
                      ].map(([id, label]) => (
                        <button
                          type="button"
                          key={id}
                          className={cn(
                            reviewDirection === id && "is-active",
                          )}
                          onClick={() =>
                            setReviewDirection(id as ReviewDirection)
                          }
                        >
                          {label}
                        </button>
                      ))}
                    </div>
                  </div>
                </div>
                <div className="wordbook-review-orbit">
                  <span className="wordbook-review-orbit__ring" />
                  <BookCheck size={44} />
                  <strong>{dueWords.length}</strong>
                  <small>due today</small>
                </div>
              </section>

              <section className="wordbook-memory-track">
                <header>
                  <div>
                    <span className="wordbook-eyebrow">7-step curve</span>
                    <h3>记忆间隔轨道</h3>
                  </div>
                  <small>再次出现的时间会随熟练度逐渐拉长</small>
                </header>
                <div>
                  {REVIEW_INTERVALS_DAYS.map((day, index) => (
                    <article key={day}>
                      <span>{String(index + 1).padStart(2, "0")}</span>
                      <strong>{day === 0 ? "当天" : `${day} 天`}</strong>
                      <small>{index < 2 ? "至少两轮" : "长时记忆"}</small>
                    </article>
                  ))}
                </div>
              </section>

              <section className="wordbook-due-list">
                <header>
                  <div>
                    <span className="wordbook-eyebrow">Review queue</span>
                    <h3>到期队列</h3>
                  </div>
                  <span>{dueWords.length} words</span>
                </header>
                <div>
                  {dueWords.slice(0, 10).map((word) => (
                    <button
                      type="button"
                      key={word.id}
                      onClick={() => {
                        setSelectedWordId(word.id);
                        setActiveTab("words");
                      }}
                    >
                      <span>
                        <strong>{word.term}</strong>
                        <small>{word.meaningsZh.join("；")}</small>
                      </span>
                      <em>{stageLabel(word)}</em>
                      <ChevronRight size={15} />
                    </button>
                  ))}
                  {dueWords.length === 0 && (
                    <div className="wordbook-empty">
                      <Check size={24} />
                      <strong>今天的队列已清空</strong>
                      <p>下一次到期时会自动出现在这里。</p>
                    </div>
                  )}
                </div>
              </section>
            </section>
          )}
        </main>

        <aside className="wordbook-side">
          <section className="wordbook-dictionary">
            <header>
              <span className="wordbook-eyebrow">Built-in dictionary</span>
              <div>
                <Languages size={18} />
                <strong>Oxford Learner's</strong>
              </div>
              <small
                className={cn(
                  dictionaryStatus?.available && "is-available",
                )}
              >
                {dictionaryStatus?.available
                  ? `${dictionaryStatus.name} · ${dictionaryStatus.wordCount.toLocaleString()} words`
                  : "使用授权词典目录后可直接离线查询"}
              </small>
            </header>
            <form onSubmit={(event) => void handleDictionarySearch(event)}>
              <Search size={15} />
              <input
                value={dictionaryQuery}
                onChange={(event) => setDictionaryQuery(event.target.value)}
                placeholder="查一个单词或短语"
              />
              <button type="submit" aria-label="查询">
                {dictionaryLoading ? (
                  <LoaderCircle size={15} />
                ) : (
                  <ChevronRight size={15} />
                )}
              </button>
            </form>
            {dictionaryResult ? (
              <article className="wordbook-dictionary-result">
                <header>
                  <div>
                    <strong>{dictionaryResult.term}</strong>
                    <small>
                      {dictionaryResult.partOfSpeech ?? "expression"} ·{" "}
                      {dictionaryResult.pronunciation ?? "IPA pending"}
                    </small>
                  </div>
                  <button
                    type="button"
                    onClick={() =>
                      speak(dictionaryResult.term) ||
                      notify("当前浏览器不支持语音朗读")
                    }
                    aria-label="朗读"
                  >
                    <Volume2 size={14} />
                  </button>
                </header>
                <p>{dictionaryResult.meaningsZh.join("；")}</p>
                <span>{dictionaryResult.definitionEn}</span>
                <button
                  type="button"
                  className="wordbook-primary-button full-width"
                  onClick={handleDictionaryAdd}
                >
                  <BookmarkPlus size={15} />
                  加入单词本
                </button>
              </article>
            ) : (
              <div className="wordbook-dictionary-placeholder">
                <SpellCheck size={23} />
                <p>查询释义、音标、词性和搭配，并直接加入复习队列。</p>
              </div>
            )}
          </section>

          <section className="wordbook-side-progress">
            <span className="wordbook-eyebrow">Progress</span>
            <h3>记忆分布</h3>
            <div className="wordbook-progress-ring">
              <span
                style={{
                  "--progress":
                    words.length > 0
                      ? `${Math.round(
                          ((counts.review + counts.mastered) / words.length) *
                            100,
                        )}%`
                      : "0%",
                } as CSSProperties}
              />
              <strong>
                {words.length > 0
                  ? Math.round(
                      ((counts.review + counts.mastered) / words.length) * 100,
                    )
                  : 0}
                %
              </strong>
              <small>已进入复习</small>
            </div>
            <div className="wordbook-progress-rows">
              {Object.entries(masteryLabels).map(([key, label]) => (
                <div key={key}>
                  <i className={`is-${key}`} />
                  <span>{label}</span>
                  <strong>{counts[key as keyof typeof counts]}</strong>
                </div>
              ))}
            </div>
          </section>

          <button
            type="button"
            className="wordbook-corpus-import"
            onClick={() => {
              const existing = new Set(
                words.map((word) => word.term.toLowerCase()),
              );
              const additions = corpus.filter(
                (entry) => !existing.has(entry.term.toLowerCase()),
              );
              if (additions.length === 0) {
                notify("语料库中的表达已经全部加入单词本");
                return;
              }
              for (const entry of additions) {
                useVocabulary.getState().addCorpusEntry(entry);
              }
              notify(`已从语料库加入 ${additions.length} 个表达`);
            }}
            data-wordbook-corpus-import
          >
            <BookOpen size={17} />
            <span>
              <strong>从语料库补充</strong>
              <small>把已收藏表达加入复习</small>
            </span>
            <ChevronRight size={15} />
          </button>
        </aside>
      </div>

      {notice && <div className="wordbook-notice">{notice}</div>}

      {settingsOpen && (
        <BookSettings
          onClose={() => setSettingsOpen(false)}
          onSave={(patch) => {
            updateBook(patch);
            setSettingsOpen(false);
            notify("封面已更新");
          }}
        />
      )}

      {session && (
        <div className="wordbook-review-modal" role="presentation">
          <div
            className="wordbook-review-dialog"
            role="dialog"
            aria-modal="true"
            aria-label="单词复习"
          >
            <header className="wordbook-review-dialog__head">
              <div>
                <span className="wordbook-eyebrow">
                  Round {session.round} of 2
                </span>
                <strong>
                  第 {session.round} 轮 ·{" "}
                  {Math.min(session.index + 1, session.wordIds.length)}/
                  {session.wordIds.length}
                </strong>
              </div>
              <div className="wordbook-review-dialog__modes">
                <button
                  type="button"
                  className={cn(reviewMode === "flashcard" && "is-active")}
                  onClick={() => setReviewMode("flashcard")}
                >
                  <RotateCcw size={14} />
                  翻卡
                </button>
                <button
                  type="button"
                  className={cn(reviewMode === "spelling" && "is-active")}
                  onClick={() => setReviewMode("spelling")}
                >
                  <Keyboard size={14} />
                  拼写
                </button>
              </div>
              <button
                type="button"
                className="wordbook-icon-button"
                onClick={closeReview}
                aria-label="关闭复习"
              >
                <X size={17} />
              </button>
            </header>

            <div className="wordbook-review-dialog__progress">
              <i
                style={{
                  width: `${
                    ((session.index + (session.completed ? 1 : 0)) /
                      session.wordIds.length) *
                    100
                  }%`,
                }}
              />
            </div>

            {session.completed ? (
              <section className="wordbook-review-complete">
                <span>
                  <Check size={34} />
                </span>
                <small>Two rounds complete</small>
                <h2>今天的复习完成</h2>
                <p>
                  共复习 {session.wordIds.length * 2} 次。下一组单词会按艾宾浩斯
                  间隔重新出现。
                </p>
                <div>
                  <strong>{session.wordIds.length}</strong>
                  <span>words</span>
                  <strong>2</strong>
                  <span>rounds each</span>
                </div>
                <button
                  type="button"
                  className="wordbook-primary-button"
                  onClick={closeReview}
                >
                  <BookCheck size={16} />
                  返回单词书
                </button>
              </section>
            ) : currentSessionWord ? (
              <>
                {reviewMode === "flashcard" ? (
                  <>
                    <div className="wordbook-review-flip">
                      <FlipCard
                        flipped={flipped}
                        onFlipChange={setFlipped}
                        width={360}
                        height={430}
                        radius={16}
                        background="#fffdf9"
                        color="#1f2529"
                        shadow={false}
                        ariaLabel={`${currentSessionWord.term} review card`}
                        front={
                          <div className="wordbook-flip-review-face">
                          <small>
                            {reviewDirection === "english-chinese"
                              ? `${currentSessionWord.partOfSpeech ?? "expression"} · ${currentSessionWord.cefr ?? "B1-B2"}`
                              : "根据中文回忆英文"}
                          </small>
                          <strong>
                            {reviewDirection === "english-chinese"
                              ? currentSessionWord.term
                              : currentSessionWord.meaningsZh.join("；")}
                          </strong>
                          <em>
                            {reviewDirection === "english-chinese"
                              ? currentSessionWord.pronunciation ?? ""
                              : currentSessionWord.definitionEn}
                          </em>
                          <span>
                            <RotateCcw size={14} />
                            点击翻面
                          </span>
                          </div>
                        }
                        back={
                          <div className="wordbook-flip-review-face is-back">
                          <small>{stageLabel(currentSessionWord)}</small>
                          <strong>
                            {reviewDirection === "english-chinese"
                              ? currentSessionWord.meaningsZh.join("；")
                              : currentSessionWord.term}
                          </strong>
                          <em>
                            {reviewDirection === "english-chinese"
                              ? currentSessionWord.definitionEn
                              : currentSessionWord.meaningsZh.join("；")}
                          </em>
                          {currentSessionWord.examples[0] && (
                            <blockquote className="wordbook-flip-card__example">
                              {currentSessionWord.examples[0].text}
                            </blockquote>
                          )}
                          </div>
                        }
                      />
                    </div>
                    <div className="wordbook-review-actions">
                      {[
                        ["again", "忘记了", "0 天后重来"],
                        ["hard", "有点难", "保持当前间隔"],
                        ["good", "记住了", "进入下一间隔"],
                        ["easy", "很轻松", "跳过一个间隔"],
                      ].map(([rating, label, hint]) => (
                        <button
                          type="button"
                          key={rating}
                          className={`is-${rating}`}
                          onClick={() =>
                            gradeCurrentWord(rating as ReviewRating)
                          }
                        >
                          <strong>{label}</strong>
                          <small>{hint}</small>
                        </button>
                      ))}
                    </div>
                  </>
                ) : (
                  <div className="wordbook-stack-stage">
                    <Stack
                      randomRotation
                      sensitivity={85}
                      sendToBackOnClick={false}
                      animationConfig={{ stiffness: 260, damping: 22 }}
                      onSwipe={(direction) => {
                        gradeCurrentWord(
                          direction === "right" ? "good" : "again",
                        );
                        notify(
                          direction === "right"
                            ? `记住了：${currentSessionWord.term}`
                            : `需要复习：${currentSessionWord.term}`,
                        );
                      }}
                      cards={
                        session?.wordIds
                          .slice(session.index)
                          .map((wordId) => {
                            const word = words.find(
                              (entry) => entry.id === wordId,
                            );
                            if (!word) return null;
                            return (
                              <div
                                className="wordbook-stack-card"
                                key={word.id}
                              >
                                <small>{stageLabel(word)}</small>
                                <h2>{word.meaningsZh.join("；")}</h2>
                                <p>{word.definitionEn}</p>
                                <div className="wordbook-spelling-hint">
                                  <span>{word.term.slice(0, 1)}</span>
                                  {Array.from({
                                    length: Math.max(1, word.term.length - 1),
                                  }).map((_, index) => (
                                    <span key={index}>_</span>
                                  ))}
                                </div>
                                <footer>
                                  <span>← 左划不会</span>
                                  <strong>右滑记住了 →</strong>
                                </footer>
                              </div>
                            );
                          })
                          .filter(Boolean) ?? []
                      }
                    />
                  </div>
                )}
              </>
            ) : (
              <div className="wordbook-empty">
                <CircleHelp size={24} />
                <strong>复习队列暂时不可用</strong>
                <button type="button" onClick={closeReview}>
                  返回单词书
                </button>
              </div>
            )}
          </div>
        </div>
      )}
    </section>
  );
}

function BookSettings({
  onClose,
  onSave,
}: {
  onClose: () => void;
  onSave: (patch: {
    name: string;
    subtitle: string;
    description: string;
    theme: VocabularyCoverTheme;
    accent: string;
  }) => void;
}) {
  const book = useVocabulary((state) => state.book);
  const [name, setName] = useState(book.name);
  const [subtitle, setSubtitle] = useState(book.subtitle);
  const [description, setDescription] = useState(book.description);
  const [theme, setTheme] = useState<VocabularyCoverTheme>(book.theme);
  const selectedTheme =
    COVER_THEMES.find((item) => item.id === theme) ?? COVER_THEMES[0]!;

  return (
    <div className="wordbook-modal" role="presentation" onClick={onClose}>
      <div
        className="wordbook-settings-dialog"
        role="dialog"
        aria-modal="true"
        aria-label="自定义单词书封面"
        onClick={(event) => event.stopPropagation()}
      >
        <header>
          <div>
            <span className="wordbook-eyebrow">Book identity</span>
            <h2>自定义封面</h2>
          </div>
          <button
            type="button"
            className="wordbook-icon-button"
            onClick={onClose}
            aria-label="关闭"
          >
            <X size={17} />
          </button>
        </header>

        <div className="wordbook-settings-layout">
          <div
            className="wordbook-cover wordbook-cover--preview"
            style={coverStyle(theme, selectedTheme.accent)}
          >
            <span className="wordbook-cover__spine" />
            <span className="wordbook-cover__rule" />
            <small>LEAFIA · OXFORD EDITION</small>
            <strong>{name || "未命名单词书"}</strong>
            <em>{subtitle || "Leafia Wordbook"}</em>
            <i>WORDBOOK</i>
          </div>

          <div className="wordbook-settings-fields">
            <label>
              <span>封面名称</span>
              <input
                value={name}
                onChange={(event) => setName(event.target.value)}
                maxLength={28}
                autoFocus
              />
            </label>
            <label>
              <span>副标题</span>
              <input
                value={subtitle}
                onChange={(event) => setSubtitle(event.target.value)}
                maxLength={48}
              />
            </label>
            <label>
              <span>书内说明</span>
              <textarea
                value={description}
                onChange={(event) => setDescription(event.target.value)}
                maxLength={120}
              />
            </label>
            <fieldset>
              <legend>封面配色</legend>
              <div className="wordbook-theme-swatches">
                {COVER_THEMES.map((item) => (
                  <button
                    type="button"
                    key={item.id}
                    className={cn(theme === item.id && "is-active")}
                    onClick={() => setTheme(item.id)}
                    aria-label={item.label}
                    title={item.label}
                  >
                    <i style={{ background: item.accent }} />
                    <span style={{ background: item.secondary }} />
                    {theme === item.id && <Check size={13} />}
                  </button>
                ))}
              </div>
            </fieldset>
          </div>
        </div>

        <footer>
          <button
            type="button"
            className="wordbook-secondary-button"
            onClick={onClose}
          >
            取消
          </button>
          <button
            type="button"
            className="wordbook-primary-button"
            onClick={() =>
              onSave({
                name: name.trim() || "我的词汇书",
                subtitle: subtitle.trim() || "Leafia Wordbook",
                description,
                theme,
                accent: selectedTheme.accent,
              })
            }
          >
            <Check size={16} />
            保存封面
          </button>
        </footer>
      </div>
    </div>
  );
}
